                finalValue = String(rawValue).split('->').pop();
            }
            if (String(finalValue).includes('(')) {
                finalValue = String(finalValue).split('(')[0];
            }
            finalValue = String(finalValue).trim();
            element.innerText = finalValue || defaultValue;
        }

